from pathlib import Path
import json,html,re
out=Path('output/full-mark-drawing-verification')
def load(file):return json.loads((out/file).read_text(encoding='utf8'))
groups=[('ก่อนแก้','setup-results.json'),('หลังแก้','after-results.json'),('ส่งออกจริง','exports-results.json'),('รุ่น build','compiled-results.json')]
rows=[]
for label,file in groups:
    data=load(file);assert not data['productionRequests'] and not data['cloud'] and not data['errors']
    for r in data['results']:
        assert r['status']=='PASS';rows.append(f'<tr><td>{html.escape(label)}</td><td>{html.escape(r["name"])}</td><td class="pass">ผ่าน</td></tr>')
pdf=load('pdf-audit.json');assert sum(r['pages'] for r in pdf)==92
for p in pdf:assert p['tableRows']==26 and p['countsCutsWeightsUnchanged']
compiled=load('compiled-pdf-audit.json');assert compiled['tableRows']==26
for file in ['protected-config.json','reference-checksums.json']:assert all(r['unchanged'] for r in load(file))
figures=[('compiled-all-mark-context.png','หน้าจอรุ่น build หลังเปลี่ยนกลุ่มเส้นชี้ ยังมี13ตำแหน่ง'),('compiled-mobile.png','หน้าจอบนมือถือ'),('A3-05.png','A3กลุ่มท้าย:3เส้นชี้และ13ตำแหน่ง'),('Details-A3-08.png','รูปตัดที่ไม่ผ่านเหล็ก:มีชื่อMark แต่ไม่มีเส้นชี้เทียม'),('A3-contact.png','ตาราง A3 /11หน้า'),('A1-contact.png','ตาราง A1 /5หน้า'),('Details-A3-contact.png','แบบพร้อมมิติ A3 /42หน้า'),('Details-A1-contact.png','แบบพร้อมมิติ A1 /34หน้า')]
gallery=''.join(f'<figure><img loading="lazy" src="{file}" alt="{caption}"><figcaption>{caption}</figcaption></figure>' for file,caption in figures)
links=''.join(f'<li><a href="{p["file"]}">{p["file"]}</a> · {p["pages"]}หน้า · SHA256 <code>{p["sha256"]}</code></li>' for p in pdf)
report=f'''<!doctype html><html lang="th"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>v0.88 — ภาพตำแหน่งเหล็กครบทุก Mark</title><style>body{{margin:0;background:#edf2f0;color:#203940;font:16px/1.65 "Segoe UI",sans-serif}}main{{max-width:1180px;margin:auto;padding:30px}}section{{background:white;border:1px solid #d6e2dd;border-radius:12px;padding:24px;margin:20px 0}}h1,h2{{line-height:1.35}}.pass{{color:#207454}}.hold{{color:#965714}}table{{border-collapse:collapse;width:100%;font-size:14px}}td,th{{border-bottom:1px solid #ddd;padding:10px;text-align:left}}img{{max-width:100%;height:auto;border:1px solid #ddd}}figure{{margin:22px 0}}a{{color:#17694e}}code{{font-size:12px;overflow-wrap:anywhere}}</style><main><h1>v0.88 · ภาพตำแหน่งเหล็กครบทุก Mark ในแบบแบ่งหน้า</h1><p>14ตุลาคม2026 · ทดสอบในเครื่องด้วยข้อมูลสังเคราะห์ · ไม่มีRules deploymentหรือProduction requests</p>
<section><h2 class="hold">ผ่านเฉพาะชุดพัฒนา/ทดสอบ — ยังไม่ผ่านตรวจรับระบบเต็ม</h2><p>แก้การส่งออกที่แสดงเฉพาะเหล็กในกลุ่มตารางหน้านั้น ให้มีเหล็กทุกMarkประกอบการอ่านตำแหน่ง สีเขียวและเส้นชี้ระบุกลุ่มตาราง สีเทาแสดงMarkอื่นที่อยู่ร่วมกัน รูปตัดยังแสดงเฉพาะเหล็กที่ผ่านแนวจริง</p><p>กรณีก่อนแก้:หน้ากลุ่มท้ายมีเพียง3จาก13ตำแหน่ง หลังแก้ครบ13ตำแหน่งในแปลน/รูปตัดขวาง พร้อมเส้นชี้เฉพาะ3Markเดิม จำนวนตาราง ยาวตัด น้ำหนัก และข้อมูลFrozenไม่เปลี่ยน ไม่มีการสร้างตำแหน่งเหล็กจากการคาดเดา</p></section>
<section><h2>ผลและขอบเขตตรวจ</h2><p>Unit tests1492กรณี/107ไฟล์ผ่าน · TypeScript/buildผ่าน คำเตือนdependencyและขนาดbundleยังมีอยู่ ไม่ถือเป็นการรับรองperformanceโครงการจริง</p><table><thead><tr><th>ช่วง</th><th>หลักฐาน</th><th>ผล</th></tr></thead><tbody>{''.join(rows)}</tbody></table><p>ไฟล์จริงทั้ง4ฉบับรวม92หน้า ขนาดA3/A1ตรง เลขแผ่น/กรอบเจ้าของงานครบ ใช้PDFvectorตรวจพิกัด13ตำแหน่งแปลนในทุกหน้ารูปจริง และ13จุดในรูปตัดขวาง ส่วนรูปตัดด้านข้างที่ไม่ผ่านเหล็กไม่มีจุดหรือเส้นชี้เทียม คำอธิบายอยู่เหนือหัวตาราง</p><p>แต่ละไฟล์มี26แถวตาราง:13Markปรากฏซ้ำสำหรับสองรูปตัดตามการนำเสนอ Each=1/Total=3/Cut=1800mm/Weight=4.794kgต่อกลุ่ม รวมปริมาณจากBBSต้นฉบับครั้งเดียว การมีรูปซ้ำไม่เพิ่มรายการเหล็ก</p><p>Exportจากปุ่มBBS A3ในแอปbuildจริงผ่าน และhashไฟล์ดาวน์โหลดตรงกับงานCompleteที่บันทึกไว้ ข้อมูลสมาชิก/Frozenเทียบตรงเดิม ไฟล์compiledตรวจแบบเดียวกันในตำแหน่งชั่วคราว ไม่เพิ่มเป็นไฟล์ส่งมอบ</p><p>หลักฐาน: <a href="setup-results.json">ก่อนแก้</a> · <a href="after-results.json">หลังแก้</a> · <a href="exports-results.json">งานส่งออก</a> · <a href="compiled-results.json">รุ่น build</a> · <a href="pdf-audit.json">PDFvectors/tables/hash</a> · <a href="compiled-pdf-audit.json">ไฟล์จากปุ่มจริง</a></p></section>
<section><h2>การอ่านแบบและข้อจำกัด</h2><p>ชื่อMarkยาวตัดบรรทัดตามพื้นที่ภาพ ระยะช่องชื่อปรับให้ใช้ความสูงมากขึ้น Markที่ไม่ตัดผ่านแสดงชื่อพร้อม(no intersection)โดยไม่มีleader รูปที่สร้างจากสมาชิกยังเป็นNTS ไม่ใช้แทนแบบต้นทางหรืออนุมัติตำแหน่งติดตั้ง</p><p>Renderทุกหน้า ตรวจcontact sheetครบทั้ง4ชุด และขยายหน้ากลุ่มท้าย/รูปตัดไม่ผ่าน ไม่อ้างว่าอ่านรายละเอียดทางวิศวกรรมทุกหน้าหรือทดสอบการพิมพ์จริง เครื่องพิมพ์และแบบโครงการหนาแน่นยังต้องตรวจรับ เพิ่มบริบทเหล็กทำให้ไฟล์ที่มีหลายMarkซับซ้อนขึ้น จึงต้องทดสอบperformanceด้วยโครงการจริง</p><p>ชุดนี้13เหล็กตรงวางตำแหน่งสังเคราะห์ ไม่ใช่การจำลองแบบGULFที่อนุมัติแล้ว กฎBS/ACIระยะฝัง/ทาบ/ระยะเรียงและIssuedยังไม่ผ่านตรวจรับ <a href="../../docs/FULL_MARK_DRAWINGS.md">คู่มือ</a> · <a href="../../docs/REQUIREMENTS_MATRIX.md">งานเดิมทั้ง12ข้อ</a></p></section>
<section><h2>ผลไม่ผ่านระหว่างเตรียมการ</h2><p>Harnessแรกใช้คำสั่งupdateProjectที่ไม่มีในแอป: <a href="setup-command-failure.json">ผลเดิม</a> เปลี่ยนเป็นsaveProjectตามimplementationและใช้โครงการQAเดิมต่อจนผ่าน การหาไฟล์renderครั้งแรกใช้ชื่อไม่ตรงรูปแบบเลขหน้า และauditซ้ำเผลอรวมcontact imageเป็นหน้าPDF แก้เฉพาะเครื่องมือตรวจและตรวจซ้ำผ่าน ไม่ใช่การซ่อมข้อมูลหรือยอมรับผลเทียม PyMuPDFไม่มีในruntime ใช้pdfplumberตรวจvectors/textและPopplerrenderแทน</p></section>
<section><h2>ไฟล์ตัวอย่างจากแอปจริง</h2><p>ทุกฉบับเป็นFrozen/DRAFT/NOT FOR CONSTRUCTION เพื่อทดสอบการแบ่งหน้า/ตำแหน่งเท่านั้น</p><ul>{links}</ul></section><section><h2>ภาพหลักฐาน</h2>{gallery}</section>
<section><h2>สิทธิ์และงานที่ยังเหลือ</h2><p>Rules/Auth/.env/firebase configurationไม่ได้แก้protected9และต้นฉบับGULF7hashตรงเดิม ไม่เพิ่มCloud Functions ไม่deployและไม่ติดต่อProduction การจัดการRulesเป็นของผู้ใช้</p><p>ยังเปิดข้อกำหนดเดิมทั้ง12ข้อ:ข้อมูลโครงการจริงทุกประเภท ตำแหน่งMarkตรงต้นทาง กฎวิศวกรรมที่รับรอง งานส่งBBSเจ้าของงาน/nativeprinting positiveIssued/ConsumedและProductionภายใต้สิทธิ์เจ้าของ การกู้คืนAuthล่าสุด/Storageของโครงการอื่นจากงานก่อนยังไม่ครบ</p><p><a href="protected-config.json">protected9</a> · <a href="reference-checksums.json">GULF7ต้นฉบับ</a></p></section></main></html>'''
(out/'DEVELOPMENT_REPORT.html').write_text(report,encoding='utf8')
for link in re.findall(r'(?:href|src)="([^"]+)"',report):assert (out/link).exists(),link
(out/'verification-summary.json').write_text(json.dumps({'version':'0.88.0','unitTests':1492,'unitFiles':107,'typescript':'PASS','build':'PASS','finalPdfPages':92,'compiledActualExport':'PASS','protectedUnchanged':16,'productionRequests':False,'engineeringAccepted':False,'full12RequirementsAccepted':False},indent=2),encoding='utf8')
print('PASS public evidence report and every linked artifact')
